func init() {
	xango.RegisterStyle("github.com/elaous/gojiberry/components/datatable.css", "/* DataTable stylesheet for github.com/elaous/gojiberry/components.\n   Requires base.css for shared tokens (--gj-*), checkbox.css for\n   Selectable's checkbox column, and pagination.css if Pagination is\n   set. */\n\n.gj-datatable-wrap { display: flex; flex-direction: column; gap: 0.6em; }\n.gj-datatable { width: 100%; border-collapse: collapse; color: var(--gj-text); }\n.gj-datatable th, .gj-datatable td {\n  padding: 0.5em 0.7em;\n  text-align: left;\n  border-bottom: 1px solid var(--gj-border);\n}\n.gj-datatable thead th { font-weight: 600; background: var(--gj-bg-muted); }\n.gj-datatable-row:hover { background: var(--gj-bg-muted); }\n.gj-datatable-row-selected { background: color-mix(in srgb, var(--gj-accent) 12%, var(--gj-bg)); }\n.gj-datatable-select-col, .gj-datatable-actions-col { width: 1%; white-space: nowrap; }\n.gj-datatable-sort {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.3em;\n  border: none;\n  background: none;\n  padding: 0;\n  font: inherit;\n  font-weight: inherit;\n  color: inherit;\n  cursor: pointer;\n}\n.gj-datatable-empty-row td { text-align: center; color: var(--gj-muted); padding: 1.5em; }\n")
}
