	xango.RegisterStyle("github.com/elaous/gojiberry/components/datepicker.css", "/* DatePicker stylesheet for github.com/elaous/gojiberry/components.\n   Requires base.css for shared tokens (--gj-*). */\n\n.gj-datepicker { border: 1px solid var(--gj-border); border-radius: var(--gj-radius); padding: 0.4em; font: inherit; }\n")
