	xango.RegisterStyle("github.com/elaous/gojiberry/components/icon.css", "/* Icon stylesheet for github.com/elaous/gojiberry/components. */\n\n.gj-icon {\n  display: inline-block;\n  line-height: 1;\n  font-style: normal;\n  vertical-align: middle;\n}\n")
