	xango.RegisterStyle("github.com/elaous/gojiberry/components/textarea.css", "/* Textarea stylesheet for github.com/elaous/gojiberry/components.\n   Requires base.css for shared tokens (--gj-*). */\n\n.gj-textarea {\n  width: 100%;\n  border: 1px solid var(--gj-border);\n  border-radius: var(--gj-radius);\n  padding: 0.5em;\n  font: inherit;\n  color: var(--gj-text);\n  resize: vertical;\n}\n.gj-textarea:disabled { cursor: not-allowed; opacity: 0.6; }\n")
